macro.command:
// Counter Mage feat macro
// Abjuration-Breaker: preAttackRoll suppresses + stores on workflow, postActiveEffects/preCleanup restore directly.
// Cleanup effect on target (1-turn) stores recovery data in its flags for crash/reload safety.
// Antimagic Shot: postActiveEffects creates, DAE on/off manages spellcasting block hook.
const macroPass = args[0].macroPass ?? args[0];
const socket = MidiQOL.socket();
const PHYSICAL_TYPES = new Set(["weapon", "equipment", "tool", "consumable", "container", "loot"]);

function isSpellActivity(activity) {
  return activity?.item?.type === "spell" || activity?.type === "cast";
}

function isMagicalEffect(ef) {
  if (ef.type === "enchantment") return true;
  if (!ef.origin) return false;
  const originItem = MidiQOL.getItemFromEffectOrigin(ef.origin);
  return originItem?.type === "spell" || originItem?.system?.properties?.has?.("mgc");
}

async function batchUpdateEffects(entries, disabled) {
  const byParent = new Map();
  for (const entry of entries) {
    if (!entry.parentUuid) continue;
    if (!byParent.has(entry.parentUuid)) byParent.set(entry.parentUuid, []);
    byParent.get(entry.parentUuid).push({ _id: entry.id, disabled });
  }
  for (const [parentUuid, updates] of byParent) {
    await socket.executeAsGM("updateEffects", { actorUuid: parentUuid, updates });
  }
}

// Collect suppression data (no DB writes)
function collectSuppressData(targetActor) {
  const suppressedEffects = [];
  for (const ef of targetActor.allApplicableEffects()) {
    if (ef.disabled || !isMagicalEffect(ef)) continue;
    suppressedEffects.push({ parentUuid: ef.parent?.uuid, id: ef.id });
  }
  const suppressedItemIds = [];
  const itemUpdates = [];
  for (const item of targetActor.items) {
    if (!PHYSICAL_TYPES.has(item.type) || !item.system?.properties?.has?.("mgc")) continue;
    suppressedItemIds.push(item.id);
    itemUpdates.push({ _id: item.id, "system.properties": [...item.system.properties].filter(p => p !== "mgc") });
  }
  return { suppressedEffects, suppressedItemIds, itemUpdates };
}

// Apply suppression (DB writes only)
async function suppressTarget(targetActor, suppData) {
  await batchUpdateEffects(suppData.suppressedEffects, true);
  if (suppData.itemUpdates.length) {
    await socket.executeAsGM("updateItems", { actorUuid: targetActor.uuid, updates: suppData.itemUpdates });
  }
}

// Restore from suppression data
async function restoreFromData(targetActor, suppData) {
  await batchUpdateEffects(suppData.suppressedEffects, false);
  const itemUpdates = [];
  for (const itemId of suppData.suppressedItemIds) {
    const item = targetActor.items.get(itemId);
    if (item && !item.system?.properties?.has?.("mgc")) {
      itemUpdates.push({ _id: itemId, "system.properties": [...(item.system?.properties ?? []), "mgc"] });
    }
  }
  if (itemUpdates.length) {
    await socket.executeAsGM("updateItems", { actorUuid: targetActor.uuid, updates: itemUpdates });
  }
}

// Restore all targets from workflow data, delete cleanup effects, clean up hooks
async function cleanupAbjurationBreaker(wf) {
  const data = wf.counterMagicData;
  if (!data) return;
  for (const target of data.targets) {
    const doc = fromUuidSync(target.actorUuid);
    const targetActor = doc instanceof TokenDocument ? doc.actor : doc;
    if (targetActor) await restoreFromData(targetActor, target.suppData);
  }
  for (const effectUuid of data.cleanupEffectUuids) {
    await socket.executeAsGM("removeEffect", { effectUuid });
  }
  if (data.reactionFilterHookId !== undefined) {
    Hooks.off("midi-qol.ReactionFilter", data.reactionFilterHookId);
  }
  delete wf.counterMagicData;
}

if (["on", "off", "init"].includes(macroPass)) {
  const lastArg = args[args.length - 1];
  const effectName = lastArg?.efData?.name ?? "";

  if (effectName === "Antimagic Shot") {
    const oldHookId = actor.getFlag("midi-qol", "antimagicShotHookId");
    if (oldHookId !== undefined) {
      Hooks.off("dnd5e.preUseActivity", oldHookId);
      await actor.unsetFlag("midi-qol", "antimagicShotHookId");
    }
    if (macroPass !== "off") {
      const targetActorUuid = lastArg.actorUuid;
      const hookId = Hooks.on("dnd5e.preUseActivity", (activity) => {
        if (activity.actor?.uuid !== targetActorUuid) return;
        if (isSpellActivity(activity)) {
          ui.notifications.warn(`${activity.actor.name}: Antimagic Shot prevents spellcasting!`);
          return false;
        }
      });
      await actor.setFlag("midi-qol", "antimagicShotHookId", hookId);
    }
    return;
  }

  // Crash/reload recovery: effect expired without normal cleanup — read data from effect flags
  if (effectName === "Abjuration-Breaker Suppression" && macroPass === "off") {
    const suppData = lastArg.efData?.flags?.["midi-qol"]?.suppData;
    if (suppData) await restoreFromData(actor, suppData);
  }
  return;
}

if (macroPass === "preCleanup") {
  await cleanupAbjurationBreaker(workflow);
  return;
}

if (macroPass === "preAttackRoll") {
  if (!["rwak", "rsak"].includes(rolledActivity?.actionType)) return;

  const targetUuids = new Set([...workflow.targets].map(t => t.actor?.uuid).filter(Boolean));
  const reactionFilterId = Hooks.on("midi-qol.ReactionFilter", (reactions, options, triggerType, reactionActivityList) => {
    if (!reactions.length || !targetUuids.has(reactions[0]?.actor?.uuid)) return;
    for (let i = reactions.length - 1; i >= 0; i--) {
      if (isSpellActivity(reactions[i])) {
        reactions.splice(i, 1);
        reactionActivityList.splice(i, 1);
      }
    }
  });

  workflow.counterMagicData = { targets: [], cleanupEffectUuids: [], reactionFilterHookId: reactionFilterId };

  for (const target of workflow.targets) {
    const targetActor = target.actor;
    if (!targetActor || targetActor.uuid === actor.uuid) continue;

    // Collect and apply suppression
    const suppData = collectSuppressData(targetActor);
    await suppressTarget(targetActor, suppData);
    workflow.counterMagicData.targets.push({ actorUuid: targetActor.uuid, suppData });

    // Cleanup effect stores suppData in its flags for crash/reload recovery via DAE "off"
    const created = await MidiQOL.createEffects({ actorUuid: targetActor.uuid, effects: [{
      name: "Abjuration-Breaker Suppression",
      icon: macroItem.img,
      origin: macroItem.uuid,
      transfer: false,
      duration: { turns: 1 },
      changes: [{ key: "macro.itemMacro", mode: 0, value: "ItemMacro", priority: 20 }],
      flags: {
        dae: { stackable: "none", transfer: false, showIcon: true },
        "midi-qol": { suppData: { suppressedEffects: suppData.suppressedEffects, suppressedItemIds: suppData.suppressedItemIds } }
      }
    }]});
    // socketlib serializes return — use _id to find the actual effect document
    const createdId = created?.[0]?._id ?? created?.[0]?.id;
    const cleanupEffect = createdId ? targetActor.effects.get(createdId) : undefined;
    if (cleanupEffect?.uuid) workflow.counterMagicData.cleanupEffectUuids.push(cleanupEffect.uuid);
  }

  // CPR's Mirror Image may remove targets even though its effect is suppressed — re-add them
  const abWorkflowId = workflow.id;
  Hooks.once("midi-qol.premades.postAttackRollComplete", (wf) => {
    if (wf.id !== abWorkflowId) return;
    for (const target of wf.targets) {
      if (wf.hitTargets.has(target) || wf.isFumble) continue;
      const targetAC = target.actor?.system?.attributes?.ac?.value;
      if (targetAC !== undefined && wf.attackTotal >= targetAC) wf.hitTargets.add(target);
    }
  });

  return;
}

if (macroPass === "postActiveEffects") {
  await cleanupAbjurationBreaker(workflow);

  if (workflow.isCritical) {
    for (const target of workflow.hitTargets) {
      const targetActor = target.actor;
      if (!targetActor) continue;
      const gutShot = targetActor.appliedEffects.find(e => e.name === "Gut Shot" && !e.disabled);
      if (!gutShot) continue;

      const created = await MidiQOL.createEffects({ actorUuid: targetActor.uuid, effects: [{
        name: "Antimagic Shot",
        icon: macroItem.img,
        origin: macroItem.uuid,
        transfer: false,
        duration: { rounds: 10 },
        changes: [
          { key: "flags.midi-qol.disadvantage.concentration", mode: 5, value: "1", priority: 20 },
          { key: "macro.itemMacro", mode: 0, value: "ItemMacro", priority: 20 }
        ],
        flags: {
          dae: { stackable: "none", transfer: false, showIcon: true }
        }
      }]});
      // Mark Antimagic Shot as a dependent of Gut Shot so it is removed automatically when Gut Shot ends.
      const createdId = created?.[0]?._id ?? created?.[0]?.id;
      const antimagicShot = createdId ? targetActor.effects.get(createdId) : undefined;
      if (antimagicShot) await MidiQOL.addDependent(gutShot, antimagicShot);
    }
  }
  return;
}
